<?php
require __DIR__.'/includes/bootstrap.php'; require_login(); require __DIR__.'/includes/layout.php';
$stats=db()->query('SELECT COUNT(*) total, COALESCE(SUM(deaths),0) deaths, COALESCE(SUM(injured),0) injured, COALESCE(SUM(missing),0) missing FROM incidents')->fetch();
$occupancy=(int)db()->query('SELECT COALESCE(SUM(occupancy),0) FROM shelters')->fetchColumn();
$trend=db()->query('SELECT YEAR(event_date) year, COUNT(*) count FROM incidents GROUP BY YEAR(event_date) ORDER BY year')->fetchAll();
$max=$trend?max(array_column($trend,'count')):1;
$recent=db()->query('SELECT * FROM incidents ORDER BY event_date DESC,id DESC LIMIT 5')->fetchAll();
page_header('Kenali risikonya. Lindungi sesama.','dashboard'); ?>
<div class="notice">Data berasal dari database lokal Anda. Jika file demo diimpor, catatan bertanda [SIMULASI] adalah fiktif.</div>
