<div class="stats"><?php foreach ([[$stats['total'],'Kejadian tercatat'],[$stats['deaths'],'Meninggal'],[$stats['injured'],'Luka-luka'],[$stats['missing'],'Dilaporkan hilang'],[$occupancy,'Penghuni posko']] as $stat): ?><article class="panel"><strong><?=e($stat[0])?></strong><span><?=e($stat[1])?></span><small>Seluruh periode</small></article><?php endforeach; ?></div>
<div class="columns"><section class="panel"><div class="section-heading"><div><h3>Tren kejadian longsor</h3><p class="small">Jumlah kejadian per tahun</p></div><a href="data.php?kind=incidents">Lihat data ↗</a></div><?php if(!$trend): ?><p class="empty">Belum ada kejadian. <a href="form.php?kind=incidents">Tambahkan data pertama</a>.</p><?php else: ?><div class="chart" role="img" aria-label="Grafik jumlah kejadian per tahun"><?php foreach($trend as $bar): ?><div class="bar"><b><?=e($bar['count'])?></b><div style="height:<?=(int)round($bar['count']/$max*150)?>px"></div><span><?=e($bar['year'])?></span></div><?php endforeach; ?></div><p class="small">Horizontal: tahun · Vertikal: jumlah kejadian</p><?php endif; ?></section><section class="warning"><span class="eyebrow">KENALI TANDA AWAL</span><h2>Jangan tunggu<br>lereng runtuh.</h2><ul><li>Retakan baru pada tanah atau lereng.</li><li>Pohon dan tiang mulai miring.</li><li>Rembesan air yang tidak biasa.</li></ul><a href="mitigasi.php">Lihat langkah kesiapsiagaan ↗</a></section></div>
